42	export class LeaseTakenError extends Error {
43	  constructor(resource, holder, requested = undefined, available = undefined) {
44	    super(`lease for resource ${String(resource)} is already held`);
45	    this.name = 'LeaseTakenError';
46	    this.code = LeaseTakenError.code;
47	    this.resource = resource;
48	    this.holder = holder ?? null;
49	    this.requested = requested;
50	    this.available = available;
51	  }
52	}
53	LeaseTakenError.code = 'LEASE_TAKEN';
