57	    super(`quota ${String(quota)} has no room for ${requested} requested share(s)`);
58	    this.name = 'QuotaExceededError';
59	    this.code = QuotaExceededError.code;
60	    this.quota = quota;
61	    this.holder = holder ?? null;
62	    this.requested = requested;
