157	// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
158	// requests in deadline order instead of scanning every pending request, so
159	// a large waiting population costs O(expired * log n), never O(n) per call.
160	class DeadlineQueue {
161	  constructor() {
162	    this.nodes = [];
163	  }
164	
165	  get size() {
166	    return this.nodes.length;
167	  }
168	
169	  push(node) {
170	    const nodes = this.nodes;
171	    nodes.push(node);
172	    let i = nodes.length - 1;
173	    while (i > 0) {
174	      const parent = (i - 1) >> 1;
175	      if (deadlineBefore(nodes[i], nodes[parent])) {
176	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
177	        i = parent;
178	      } else {
179	        break;
180	      }
181	    }
182	  }
183	
184	  peek() {
185	    return this.nodes[0];
186	  }
187	
188	  pop() {
189	    const nodes = this.nodes;
190	    const top = nodes[0];
191	    const last = nodes.pop();
192	    if (nodes.length > 0) {
193	      nodes[0] = last;
194	      let i = 0;
195	      for (;;) {
196	        const left = i * 2 + 1;
197	        const right = left + 1;
198	        let next = i;
199	        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
200	          next = left;
201	        }
202	        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
203	          next = right;
204	        }
205	        if (next === i) {
206	          break;
207	        }
208	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
209	        i = next;
210	      }
211	    }
212	    return top;
213	  }
214	}
215	
216	function deadlineBefore(a, b) {
217	  if (a.deadline !== b.deadline) {
218	    return a.deadline < b.deadline;
219	  }
220	  return a.tie < b.tie;
221	}
