1846	      leases.delete(node.token);
1847	      if (removeSlot(lease.resource, node.token)) {
1848	        counters.reclaimed += 1;
1849	        freed.push(lease.resource);
1850	      }
1851	    }
1852	    for (const plan of plans) {
1853	      applyPlannedGrants(plan, now);
1854	    }
1855	    return freed;
1856	  }
1857	
1858	  function holder(resource) {
1859	    const now = clock();
1860	    purgeExpiredWaiters(now);
1861	    return liveHolder(resource, now);
1862	  }
1863	
1864	  // Last committed credential epoch of a resource: 0 before its first grant,
1865	  // otherwise the epoch of its most recently granted credential. Releases,
1866	  // reclaims, expiries and restarts never roll it back, so a free resource
1867	  // still reports the epoch its last credential carried.
1868	  function epoch(resource) {
1869	    return epochs.get(resource) ?? 0;
1870	  }
1871	
1872	  // Leader fence check. Returns true only when `token` is a current, live
1873	  // credential of `resource` minted in this process, carrying exactly the
1874	  // resource's last committed epoch. Every other situation - an unknown
1875	  // resource or token, a released/reclaimed/expired credential, a credential
1876	  // captured before a restart, an older epoch, or another holder's
1877	  // credential - fences the caller instead of returning false.
1878	  function assertLease(resource, token, epochValue) {
1879	    if (typeof resource !== 'string') {
1880	      throw new TypeError('resource must be a string');
1881	    }
1882	    if (typeof token !== 'string') {
1883	      throw new TypeError('token must be a string');
1884	    }
1885	    if (!Number.isInteger(epochValue)) {
1886	      throw new TypeError('epoch must be a finite integer');
1887	    }
1888	    const lease = leases.get(token);
1889	    if (
1890	      lease === undefined ||
1891	      lease.legacy ||
1892	      lease.resource !== resource ||
1893	      lease.expiresAt <= clock() ||
1894	      lease.epoch !== epochValue ||
1895	      epochs.get(resource) !== epochValue
1896	    ) {
1897	      throw new LeaseFencedError(resource);
1898	    }
1899	    return true;
1900	  }
1901	
1902	  function stats() {
1903	    const now = clock();
1904	    purgeExpiredWaiters(now);
1905	    // Reconcile each resource owner independently: work is proportional to
1906	    // the shares actually due since the last observation plus the number
1907	    // of distinct resources, never to the total number of live shares.
1908	    // Quota usage follows the same reconciliation lazily through acquires,
1909	    // releases and sweeps.
1910	    let live = 0;
1911	    for (const rs of resourceStates.values()) {
1912	      reconcile(rs, now);
1913	      live += rs.live;
1914	    }
1915	    // Resource reconciliation retires a share at the resource only; every
1916	    // quota level is an independent owner and must observe the reading too,
1917	    // so an expired share vacates ancestor room at this observation.
1918	    for (const quota of quotas.values()) {
1919	      reconcile(quota, now);
1920	    }
1921	    return {
1922	      granted: counters.granted,
1923	      renewed: counters.renewed,
1924	      released: counters.released,
1925	      reclaimed: counters.reclaimed,
1926	      live,
1927	    };
1928	  }
1929	
1930	  // Fold the whole history into one snapshot and restart the event log from
1931	  // that point. The snapshot is published first (temp + fsync + rename) and
1932	  // the trimmed log second; a failure at either step leaves the previously
1933	  // usable files in place and throws LogFileError. Credentials captured by
1934	  // the snapshot are void afterwards, exactly as across a restart.
1935	  function compact(now = clock()) {
1936	    if (logPath === null) {
1937	      throw new LogFileError('cannot compact a registry without a logPath');
1938	    }
1939	
1940	    // Read the log up front: an unreadable log must fail compaction rather
1941	    // than replacing it. Every complete line is already reflected in the
1942	    // in-memory state; an unterminated fragment at the tail (an append that
1943	    // died with the process) is folded nowhere and is dropped by the rewrite.
1944	    try {
1945	      fs.readFileSync(logPath, 'utf8');
1946	    } catch (cause) {
1947	      if (cause.code !== 'ENOENT') {
1948	        throw new LogFileError(`failed to read lease log at ${logPath}`, cause);
1949	      }
1950	    }
1951	
1952	    // The image carries every lease still in the table, including expired
1953	    // ones nobody has swept yet, so a sweep after compaction frees and counts
1954	    // them in exactly the same order as before. Only live credentials show in
1955	    // ownership and liveness either way.
1956	    //
1957	    // Equal expiry times are tie-broken by expiry-heap insertion order
1958	    // (renewals push a fresh node), so remember each lease's current node
1959	    // order and serialize in heap-pop order: reclaim order is then identical
1960	    // after a restart even when several credentials expire at the same
1961	    // instant.
1962	    const activeOrder = new Map();
1963	    for (const node of expiryQueue.nodes) {
1964	      const lease = leases.get(node.token);
1965	      if (lease !== undefined && lease.heapSeq === node.heapSeq) {
1966	        activeOrder.set(node.token, node.order);
1967	      }
1968	    }
1969	    const leaseEntries = [];
1970	    for (const [token, lease] of leases.entries()) {
1971	      leaseEntries.push({
1972	        token,
1973	        resource: lease.resource,
1974	        holder: lease.holder,
1975	        expiresAt: lease.expiresAt,
1976	        ttlMs: lease.ttlMs,
1977	        epoch: lease.epoch,
1978	        batch: lease.batch ?? null,
1979	        // Local tie-breaker for the sort below; stripped before writing.
1980	        order: activeOrder.get(token) ?? 0,
1981	      });
1982	    }
1983	    leaseEntries.sort((a, b) =>
1984	      a.expiresAt !== b.expiresAt
1985	        ? a.expiresAt - b.expiresAt
1986	        : a.order - b.order);
1987	    for (const entry of leaseEntries) {
1988	      delete entry.order;
1989	    }
1990	
1991	    // Quota forest and resource declarations come first in the image so the
1992	    // leases below can be attached to reconstructed chains; per-level quota
1993	    // occupation is rebuilt from the lease entries themselves, so the usage
1994	    // figures can never disagree with the shares they count.
1995	    const quotaEntries = [];
1996	    for (const [id, quota] of quotas.entries()) {
1997	      quotaEntries.push({ quota: id, parent: quota.parentId, limit: quota.limit });
1998	    }
1999	    const resourceEntries = [];
2000	    for (const [resource, rs] of resourceStates.entries()) {
2001	      if (rs.declared) {
2002	        const leaf = rs.chain.length === 0 ? null : rs.chain[rs.chain.length - 1].id;
2003	        resourceEntries.push({ resource, capacity: rs.capacity, quota: leaf });
2004	      }
2005	    }
2006	
2007	    // The last committed epoch of every resource that has ever been granted,
2008	    // including resources with no live credential: a free resource keeps
2009	    // reporting its last epoch after a compacted restart, and the next grant
2010	    // continues from it instead of restarting at 1.
2011	    const epochEntries = [];
2012	    for (const [resource, value] of epochs.entries()) {
2013	      epochEntries.push({ resource, epoch: value });
2014	    }
2015	
2016	    const snapshot = {
2017	      v: SNAPSHOT_VERSION,
2018	      type: 'snapshot',
2019	      at: now,
2020	      seq: eventSeq,
2021	      tokenSeq: tokenSequence,
2022	      batchSeq: batchSequence,
2023	      counters: { ...counters },
2024	      quotas: quotaEntries,
2025	      resources: resourceEntries,
2026	      epochs: epochEntries,
2027	      leases: leaseEntries,
2028	    };
2029	
2030	    // 1. Publish the snapshot. If this fails, nothing else has moved and the
2031	    //    original log stays the sole source of truth.
2032	    writeAtomic(snapshotPath, `${JSON.stringify(snapshot)}\n`);
2033	    // 2. Replace the log with a boundary marker naming the last folded event
2034	    //    sequence. Every complete line was folded into the image, so the only
2035	    //    thing dropped here is an unterminated fragment; later events append
2036	    //    after the marker. If this rename never happens after a committed
2037	    //    snapshot, startup finds no marker, folds the whole log and skips
2038	    //    every event whose sequence is already in the image; either order
2039	    //    yields each event exactly once.

